/** @type {import('jest').Config} */
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  roots: ['<rootDir>/src'],
  testMatch: ['**/*.test.ts'],
  clearMocks: true,
};

export interface PageFrontmatter {
  title: string;
  date?: string;
  tags: string[];
}

export interface Page {
  /** Slug relative to the content dir, without extension, using '/' separators. */
  slug: string;
  frontmatter: PageFrontmatter;
  contentHtml: string;
  /** Absolute path to the source markdown file. */
  sourcePath: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  /** Title used in the generated index page. */
  siteTitle?: string;
}

export interface BuildResult {
  pages: Page[];
  outputFiles: string[];
}

import matter from 'gray-matter';
import { marked } from 'marked';
import { PageFrontmatter } from './types';

marked.setOptions({ gfm: true });

function normalizeDate(value: unknown): string | undefined {
  if (value instanceof Date) {
    return value.toISOString().slice(0, 10);
  }
  if (typeof value === 'string' && value.trim().length > 0) {
    return value.trim();
  }
  return undefined;
}

function normalizeTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((tag) => String(tag).trim()).filter((tag) => tag.length > 0);
  }
  if (typeof value === 'string' && value.trim().length > 0) {
    return value
      .split(',')
      .map((tag) => tag.trim())
      .filter((tag) => tag.length > 0);
  }
  return [];
}

export interface ParsedMarkdown {
  frontmatter: PageFrontmatter;
  contentHtml: string;
}

/** Parses raw markdown (with optional YAML frontmatter) into HTML and structured frontmatter. */
export function parseMarkdown(raw: string, fallbackTitle: string): ParsedMarkdown {
  const { data, content } = matter(raw);

  const frontmatter: PageFrontmatter = {
    title: typeof data.title === 'string' && data.title.trim().length > 0 ? data.title.trim() : fallbackTitle,
    date: normalizeDate(data.date),
    tags: normalizeTags(data.tags),
  };

  const contentHtml = marked.parse(content, { async: false }) as string;

  return { frontmatter, contentHtml };
}

import { Page } from './types';

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderMeta(page: Page): string {
  const parts: string[] = [];
  if (page.frontmatter.date) {
    parts.push(`<time datetime="${escapeHtml(page.frontmatter.date)}">${escapeHtml(page.frontmatter.date)}</time>`);
  }
  if (page.frontmatter.tags.length > 0) {
    const tags = page.frontmatter.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ');
    parts.push(`<span class="tags">${tags}</span>`);
  }
  return parts.length > 0 ? `<p class="meta">${parts.join(' &middot; ')}</p>` : '';
}

export function renderPageHtml(page: Page): string {
  const title = escapeHtml(page.frontmatter.title);
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
  <link rel="stylesheet" href="${'../'.repeat(page.slug.split('/').length - 1)}style.css">
</head>
<body>
  <header>
    <a href="${'../'.repeat(page.slug.split('/').length - 1)}index.html">&larr; Back to index</a>
  </header>
  <main>
    <article>
      <h1>${title}</h1>
      ${renderMeta(page)}
      ${page.contentHtml}
    </article>
  </main>
</body>
</html>
`;
}

export function renderIndexHtml(pages: Page[], siteTitle: string): string {
  const items = pages
    .map((page) => {
      const title = escapeHtml(page.frontmatter.title);
      const href = `${page.slug}.html`;
      return `      <li>
        <a href="${escapeHtml(href)}">${title}</a>
        ${renderMeta(page)}
      </li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(siteTitle)}</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <header>
    <h1>${escapeHtml(siteTitle)}</h1>
  </header>
  <main>
    <ul class="page-list">
${items}
    </ul>
  </main>
</body>
</html>
`;
}

export const DEFAULT_STYLESHEET = `body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; color: #1a1a1a; }
a { color: #0b5fff; }
.page-list { list-style: none; padding: 0; }
.page-list li { margin-bottom: 1.25rem; }
.meta { color: #666; font-size: 0.875rem; margin: 0.25rem 0; }
.tag { background: #eee; border-radius: 0.25rem; padding: 0.1rem 0.4rem; font-size: 0.75rem; }
`;

import * as fs from 'fs';
import * as path from 'path';
import { parseMarkdown } from './markdown';
import { renderIndexHtml, renderPageHtml, DEFAULT_STYLESHEET } from './templates';
import { BuildOptions, BuildResult, Page } from './types';

function findMarkdownFiles(dir: string): string[] {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...findMarkdownFiles(fullPath));
    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
      files.push(fullPath);
    }
  }
  return files;
}

function toSlug(contentDir: string, filePath: string): string {
  const relative = path.relative(contentDir, filePath).replace(/\.md$/i, '');
  return relative.split(path.sep).join('/');
}

function titleFromSlug(slug: string): string {
  const base = slug.split('/').pop() ?? slug;
  return base
    .split(/[-_]/)
    .filter((word) => word.length > 0)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

function comparePages(a: Page, b: Page): number {
  if (a.frontmatter.date && b.frontmatter.date) {
    if (a.frontmatter.date !== b.frontmatter.date) {
      return a.frontmatter.date < b.frontmatter.date ? 1 : -1;
    }
  } else if (a.frontmatter.date) {
    return -1;
  } else if (b.frontmatter.date) {
    return 1;
  }
  return a.frontmatter.title.localeCompare(b.frontmatter.title);
}

/** Reads markdown content from contentDir, converts it to HTML, and writes the site to outputDir. */
export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;
  const siteTitle = options.siteTitle ?? 'My Site';

  if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const markdownFiles = findMarkdownFiles(contentDir).sort();

  const pages: Page[] = markdownFiles.map((filePath) => {
    const raw = fs.readFileSync(filePath, 'utf-8');
    const slug = toSlug(contentDir, filePath);
    const { frontmatter, contentHtml } = parseMarkdown(raw, titleFromSlug(slug));
    return { slug, frontmatter, contentHtml, sourcePath: filePath };
  });

  pages.sort(comparePages);

  fs.rmSync(outputDir, { recursive: true, force: true });
  fs.mkdirSync(outputDir, { recursive: true });

  const outputFiles: string[] = [];

  for (const page of pages) {
    const outputPath = path.join(outputDir, `${page.slug}.html`);
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    fs.writeFileSync(outputPath, renderPageHtml(page), 'utf-8');
    outputFiles.push(outputPath);
  }

  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, renderIndexHtml(pages, siteTitle), 'utf-8');
  outputFiles.push(indexPath);

  const stylesheetPath = path.join(outputDir, 'style.css');
  fs.writeFileSync(stylesheetPath, DEFAULT_STYLESHEET, 'utf-8');
  outputFiles.push(stylesheetPath);

  return { pages, outputFiles };
}

import { build } from './build';

export interface CliArgs {
  command: string;
  contentDir: string;
  outputDir: string;
}

const DEFAULT_CONTENT_DIR = './content';
const DEFAULT_OUTPUT_DIR = './dist';

export function parseArgs(argv: string[]): CliArgs {
  const [command = 'build', ...rest] = argv;
  let contentDir = DEFAULT_CONTENT_DIR;
  let outputDir = DEFAULT_OUTPUT_DIR;

  for (let i = 0; i < rest.length; i++) {
    const arg = rest[i];
    if (arg === '--content') {
      const value = rest[i + 1];
      if (!value) throw new Error('--content requires a directory argument');
      contentDir = value;
      i++;
    } else if (arg === '--output') {
      const value = rest[i + 1];
      if (!value) throw new Error('--output requires a directory argument');
      outputDir = value;
      i++;
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }

  return { command, contentDir, outputDir };
}

export function run(argv: string[]): void {
  const args = parseArgs(argv);

  if (args.command !== 'build') {
    throw new Error(`Unknown command: ${args.command}. Supported commands: build`);
  }

  const result = build({ contentDir: args.contentDir, outputDir: args.outputDir });
  // eslint-disable-next-line no-console
  console.log(`Built ${result.pages.length} page(s) from ${args.contentDir} to ${args.outputDir}`);
}

export function main(): void {
  try {
    run(process.argv.slice(2));
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    // eslint-disable-next-line no-console
    console.error(`ssg: ${message}`);
    process.exitCode = 1;
  }
}

if (require.main === module) {
  main();
}

import { parseMarkdown } from './markdown';

describe('parseMarkdown', () => {
  it('extracts title, date, and tags from frontmatter', () => {
    const raw = `---
title: My Post
date: 2026-02-01
tags: [foo, bar]
---

# Heading

Some **bold** text.
`;
    const { frontmatter, contentHtml } = parseMarkdown(raw, 'Fallback');

    expect(frontmatter.title).toBe('My Post');
    expect(frontmatter.date).toBe('2026-02-01');
    expect(frontmatter.tags).toEqual(['foo', 'bar']);
    expect(contentHtml).toContain('<h1>Heading</h1>');
    expect(contentHtml).toContain('<strong>bold</strong>');
  });

  it('falls back to the provided title when frontmatter has none', () => {
    const raw = `No frontmatter here.`;
    const { frontmatter } = parseMarkdown(raw, 'Fallback Title');
    expect(frontmatter.title).toBe('Fallback Title');
  });

  it('normalizes a comma separated tags string', () => {
    const raw = `---
title: Tagged
tags: one, two, three
---
Body`;
    const { frontmatter } = parseMarkdown(raw, 'Fallback');
    expect(frontmatter.tags).toEqual(['one', 'two', 'three']);
  });

  it('defaults tags to an empty array when absent', () => {
    const raw = `---
title: No Tags
---
Body`;
    const { frontmatter } = parseMarkdown(raw, 'Fallback');
    expect(frontmatter.tags).toEqual([]);
  });

  it('normalizes a YAML date value (parsed as a Date object) to YYYY-MM-DD', () => {
    const raw = `---
title: Dated
date: 2026-03-15
---
Body`;
    const { frontmatter } = parseMarkdown(raw, 'Fallback');
    expect(frontmatter.date).toBe('2026-03-15');
  });

  it('leaves date undefined when absent', () => {
    const raw = `---
title: No Date
---
Body`;
    const { frontmatter } = parseMarkdown(raw, 'Fallback');
    expect(frontmatter.date).toBeUndefined();
  });
});

import { escapeHtml, renderIndexHtml, renderPageHtml } from './templates';
import { Page } from './types';

function makePage(overrides: Partial<Page> = {}): Page {
  return {
    slug: 'hello',
    frontmatter: { title: 'Hello', date: '2026-01-01', tags: ['a', 'b'] },
    contentHtml: '<p>Body</p>',
    sourcePath: '/content/hello.md',
    ...overrides,
  };
}

describe('escapeHtml', () => {
  it('escapes special characters', () => {
    expect(escapeHtml('<script>alert("x")</script>')).toBe(
      '&lt;script&gt;alert(&quot;x&quot;)&lt;/script&gt;'
    );
  });
});

describe('renderPageHtml', () => {
  it('includes the title, meta, and content', () => {
    const html = renderPageHtml(makePage());
    expect(html).toContain('<title>Hello</title>');
    expect(html).toContain('<p>Body</p>');
    expect(html).toContain('2026-01-01');
    expect(html).toContain('a');
    expect(html).toContain('b');
  });

  it('escapes an untrusted title', () => {
    const page = makePage({ frontmatter: { title: '<img src=x>', date: undefined, tags: [] } });
    const html = renderPageHtml(page);
    expect(html).not.toContain('<img src=x>');
    expect(html).toContain('&lt;img src=x&gt;');
  });

  it('links back to a nested index correctly', () => {
    const page = makePage({ slug: 'posts/hello' });
    const html = renderPageHtml(page);
    expect(html).toContain('href="../index.html"');
  });
});

describe('renderIndexHtml', () => {
  it('lists every page with a link to its file', () => {
    const pages = [makePage({ slug: 'a', frontmatter: { title: 'A', tags: [] } }), makePage({ slug: 'b', frontmatter: { title: 'B', tags: [] } })];
    const html = renderIndexHtml(pages, 'My Site');
    expect(html).toContain('<title>My Site</title>');
    expect(html).toContain('href="a.html"');
    expect(html).toContain('href="b.html"');
    expect(html).toContain('>A<');
    expect(html).toContain('>B<');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { build } from './build';

function makeTempDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('build', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = makeTempDir('ssg-content-');
    outputDir = makeTempDir('ssg-output-');
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('throws a clear error when the content directory does not exist', () => {
    expect(() => build({ contentDir: path.join(contentDir, 'missing'), outputDir })).toThrow(
      /Content directory not found/
    );
  });

  it('generates an HTML file per markdown page plus an index', () => {
    fs.writeFileSync(
      path.join(contentDir, 'first.md'),
      '---\ntitle: First Post\ndate: 2026-01-02\ntags: [x]\n---\n\n# First\n\nHello.'
    );
    fs.writeFileSync(
      path.join(contentDir, 'second.md'),
      '---\ntitle: Second Post\ndate: 2026-01-05\n---\n\n# Second\n\nWorld.'
    );

    const result = build({ contentDir, outputDir, siteTitle: 'Test Site' });

    expect(result.pages).toHaveLength(2);
    expect(fs.existsSync(path.join(outputDir, 'first.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'second.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(indexHtml).toContain('Test Site');
    expect(indexHtml).toContain('First Post');
    expect(indexHtml).toContain('Second Post');

    const firstHtml = fs.readFileSync(path.join(outputDir, 'first.html'), 'utf-8');
    expect(firstHtml).toContain('<h1>First</h1>');
    expect(firstHtml).toContain('Hello.');
  });

  it('sorts pages by date descending, newest first, in the index', () => {
    fs.writeFileSync(path.join(contentDir, 'old.md'), '---\ntitle: Old\ndate: 2020-01-01\n---\nOld content');
    fs.writeFileSync(path.join(contentDir, 'new.md'), '---\ntitle: New\ndate: 2026-01-01\n---\nNew content');

    const result = build({ contentDir, outputDir });
    expect(result.pages.map((p) => p.frontmatter.title)).toEqual(['New', 'Old']);
  });

  it('supports nested content directories and mirrors the structure in dist', () => {
    fs.mkdirSync(path.join(contentDir, 'posts'));
    fs.writeFileSync(
      path.join(contentDir, 'posts', 'nested.md'),
      '---\ntitle: Nested Post\n---\nNested content'
    );

    const result = build({ contentDir, outputDir });
    expect(result.pages[0].slug).toBe('posts/nested');
    expect(fs.existsSync(path.join(outputDir, 'posts', 'nested.html'))).toBe(true);
  });

  it('derives a title from the filename when frontmatter has none', () => {
    fs.writeFileSync(path.join(contentDir, 'no-frontmatter.md'), '# Just Content\n\nNo frontmatter at all.');
    const result = build({ contentDir, outputDir });
    expect(result.pages[0].frontmatter.title).toBe('No Frontmatter');
  });

  it('cleans previously generated output before rebuilding', () => {
    fs.writeFileSync(path.join(outputDir, 'stale.html'), 'stale');
    fs.writeFileSync(path.join(contentDir, 'page.md'), '---\ntitle: Page\n---\nContent');

    build({ contentDir, outputDir });

    expect(fs.existsSync(path.join(outputDir, 'stale.html'))).toBe(false);
  });

  it('writes a stylesheet used by the generated pages', () => {
    fs.writeFileSync(path.join(contentDir, 'page.md'), '---\ntitle: Page\n---\nContent');
    build({ contentDir, outputDir });
    expect(fs.existsSync(path.join(outputDir, 'style.css'))).toBe(true);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { parseArgs, run } from './cli';

describe('parseArgs', () => {
  it('defaults to the build command with default directories', () => {
    expect(parseArgs(['build'])).toEqual({
      command: 'build',
      contentDir: './content',
      outputDir: './dist',
    });
  });

  it('parses --content and --output overrides', () => {
    expect(parseArgs(['build', '--content', './src-content', '--output', './public'])).toEqual({
      command: 'build',
      contentDir: './src-content',
      outputDir: './public',
    });
  });

  it('throws when --content is missing its value', () => {
    expect(() => parseArgs(['build', '--content'])).toThrow(/--content requires/);
  });

  it('throws on an unknown flag', () => {
    expect(() => parseArgs(['build', '--bogus'])).toThrow(/Unknown argument/);
  });
});

describe('run', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-cli-content-'));
    outputDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-cli-output-'));
    fs.writeFileSync(path.join(contentDir, 'page.md'), '---\ntitle: Page\n---\nHello');
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('builds the site end-to-end via the CLI entrypoint', () => {
    run(['build', '--content', contentDir, '--output', outputDir]);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'page.html'))).toBe(true);
  });

  it('rejects an unknown command', () => {
    expect(() => run(['deploy'])).toThrow(/Unknown command/);
  });
});
